mapper.sql:
from sys_localization_entry e
join sys_localization_namespace n on n.id = e.namespace_id and n.deleted = 0
left join sys_localization_translation t_target
  on t_target.entry_id = e.id
 and t_target.locale_code = #{query.targetLocale}
 and t_target.deleted = 0
left join sys_localization_translation t_fallback
  on t_fallback.entry_id = e.id
 and t_fallback.locale_code = #{query.fallbackLocale}
 and t_fallback.deleted = 0
left join (
    select entry_id, count(1) as usage_count
    from sys_localization_usage_ref
    where deleted = 0
    group by entry_id
) u on u.entry_id = e.id
where e.deleted = 0

  and n.namespace_code = #{query.namespaceCode}


  and (
        e.message_key like #{query.keywordLike}
     or e.default_message like #{query.keywordLike}
     or n.namespace_name like #{query.keywordLike}
     or e.source_ref like #{query.keywordLike}
  )


  and e.status = #{query.status}


  and coalesce(t_target.translated_message, t_fallback.translated_message, '') <> ''


  and coalesce(t_target.translated_message, t_fallback.translated_message, '') = ''
